def check_paras(paras):
    total = 0
    for idx, p in enumerate(paras, 1):
        words = p.split()
        pw = len(words)
        total += pw
        print(f"P{idx:02d}: {pw} words")
        if pw < 65 or pw > 135:
            print(f"  [ERROR] P{idx} length {pw} out of range [65, 135]")
    print(f"TOTAL: {total} words (must be 1550-1850)")
    print(f"PARAS: {len(paras)} (must be 16-18)")

check_paras(ch01_paras)
